INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 2, 1000, "vo_minigame_1013_icon_2_002_001", 1, "調子が上がって\nきたなっ", 3000, "訓練はまだ\nここからですわ", "vo_minigame_1013_icon_1_002_001", 2);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 2, 5000, "vo_minigame_1013_icon_2_003_001", 2, "ほらほら、\nまだいけるだろ？", 3000, "クスクス、悪くない\n流れですわね", "vo_minigame_1013_icon_1_003_001", 2);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 2, 10000, "vo_minigame_1013_icon_2_004_001", 3, "へへっ、おまえら\nやるじゃねえか！", 3000, "すばらしい\n記録ですわ", "vo_minigame_1013_icon_1_004_001", 3);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 3, 10000, "vo_minigame_1013_icon_2_005_001", 4, "あたしたちはまだ\n止まらねえぜ！", 3000, "乗りに乗って\nいますわね", "vo_minigame_1013_icon_1_005_001", 3);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 3, 10000, "vo_minigame_1013_icon_2_005_002", 5, "見てろよ！\nマコト班の快進撃だ！", 3000, "まだまだ行きます\nついてきなさい", "vo_minigame_1013_icon_1_005_002", 3);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 3, 10000, "vo_minigame_1013_icon_2_005_003", 6, "うおぉぉっ！\n絶好調だぜ！", 3000, "エリコ班の\n本領発揮ですわ！", "vo_minigame_1013_icon_1_005_003", 3);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (2, 4, 0, "vo_minigame_1013_icon_2_006_001", 7, "どこまで行けるか\n楽しみだなっ！", 3000, "ここからは\n前人未到の領域です！", "vo_minigame_1013_icon_1_006_001", 3);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3, 5, 1, "vo_minigame_1013_icon_2_007_001", 8, "まだ諦めんなよっ", 1000, "厄介でしたわ…", "vo_minigame_1013_icon_1_007_001", 4);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3, 5, 1, "vo_minigame_1013_icon_2_007_002", 9, "冷やっとしたぜ…！", 1000, "油断大敵です", "vo_minigame_1013_icon_1_007_002", 4);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (3, 5, 1, "vo_minigame_1013_icon_2_007_003", 10, "弱音を吐くなっ", 1000, "忌々しいっ…", "vo_minigame_1013_icon_1_007_003", 4);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (4, 6, 99, "vo_minigame_1013_icon_2_008_001", 11, "マコト班集合！", 1500, "大所帯ですわね", "vo_minigame_1013_icon_1_008_001", 3);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (4, 6, 99, "vo_minigame_1013_icon_2_008_002", 12, "連携してくぞ！", 1500, "エリコ班へようこそ", "vo_minigame_1013_icon_1_008_002", 3);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (1, 8, 0, "vo_minigame_1013_icon_2_020_001", 13, "みんなに力を！", 3000, "ナナカちゃんに\nお任せあれ", "vo_minigame_1013_icon_1_020_001", 6);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (1, 9, 0, "vo_minigame_1013_icon_2_022_001", 14, "任せてくれたまえ", 3000, "はっはっは！\n任せろ！", "vo_minigame_1013_icon_1_022_001", 7);
INSERT INTO `v1_79dd0b8e17e3a02a9bde262ff937907d2d64ff23964a4c97b48045bd1576f330` VALUES (1, 10, 0, "vo_minigame_1013_icon_2_023_001", 15, "ほな、いきまひょか", 3000, "どんどんいくわよ", "vo_minigame_1013_icon_1_023_001", 8);
